ruleset:
table inet frisket {
  set relay4 { type ipv4_addr . inet_service; }
  set relay6 { type ipv6_addr . inet_service; }
  chain steer {
    type route hook output priority mangle; policy accept;
    socket transparent 1 return
    meta l4proto { tcp, udp } th dport 53 meta mark set 1 return
    ip daddr . tcp dport @relay4 meta mark set 1 return
    ip6 daddr . tcp dport @relay6 meta mark set 1 return
    ip daddr 192.0.2.2 meta l4proto tcp meta mark set 1 return
    ip6 daddr 2001:db8::2 meta l4proto tcp meta mark set 1 return
    fib daddr type local return
    meta l4proto tcp meta mark set 1 return
  }
  chain pre {
    type filter hook prerouting priority mangle; policy accept;
    meta mark != 1 return
    meta nfproto ipv4 meta l4proto tcp tproxy ip to 127.0.0.1:15001 accept
    meta nfproto ipv6 meta l4proto tcp tproxy ip6 to [::1]:15001 accept
    meta nfproto ipv4 udp dport 53 tproxy ip to 127.0.0.1:53 accept
    meta nfproto ipv6 udp dport 53 tproxy ip6 to [::1]:53 accept
    meta l4proto tcp reject with tcp reset
    reject with icmpx admin-prohibited
  }
  # Everything that is neither marked nor local is refused. `meta mark`
  # first: a marked packet's route is lo, but it is not addressed to a
  # local address, and the local rule would not let it through.
  chain out_filter {
    type filter hook output priority filter; policy drop;
    meta mark 1 accept
    fib daddr type local accept
    reject with icmpx admin-prohibited
  }
  chain guard {
    type filter hook postrouting priority filter; policy accept;
    meta mark 1 oifname != "lo" drop
  }
}
